"""
    Ensures input can be compared to float, in case input is
    string with inequalities
    """
def to_float(MIC: Any) -> object {
    MIC = str(MIC);
    for equality_smb in ['=', '<', '>'] {
        MIC = MIC.replace(equality_smb, '');
    }
    return float(MIC);
}

